HelmholtzParticles.customGLSL:
// @node helmholtzParticles
// @title Helmholtz Particles
// @category custom
// @description Particle state update for a 64x5 rgba32f / nearest Feedback (wire its out back into state). Each column is one particle advected through the hyperbolic Helmholtz flow v = grad phi + J grad psi with RK4 (dt from the clock stored in the state). Particles respawn near sources (or anywhere) when their life ends, they reach the disk rim, or a sink swallows them. Rows: 0 (u.xy, age, gen) | 1 (previous u.xy, dt, time) | 2 (velocity.xy, tanh(phi), life) | 3 lifted centre on the H3 hyperboloid | 4 (radius, source-to-sink tint, speed, envelope).
// ---- Shared Helmholtz field on the hyperbolic plane (Poincare disk coordinates u, |u| < 1) ----
// 7 smooth kernels: 2 sources, 2 sinks, 3 vortices whose centres drift on bounded paths.

vec3 hp_hash3(uvec3 v) {
    v = v * 1664525u + 1013904223u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    v ^= v >> 16u;
    v.x += v.y * v.z; v.y += v.z * v.x; v.z += v.x * v.y;
    return vec3(v) * (1.0 / 4294967296.0);
}

// Kernel centre k at time t (0,1 sources | 2,3 sinks | 4,5,6 vortices)
vec2 hp_center(int k, float t) {
    float fk = float(k);
    float ang = 0.0;
    float rad = 0.0;
    if (k == 0) { ang = 0.0; rad = 0.32; }
    else if (k == 1) { ang = 3.14159; rad = 0.32; }
    else if (k == 2) { ang = 1.5708; rad = 0.34; }
    else if (k == 3) { ang = 4.7124; rad = 0.34; }
    else if (k == 5) { ang = 0.7854; rad = 0.46; }
    else if (k == 6) { ang = 3.9270; rad = 0.46; }
    ang += -t * 0.012 + 0.3 * sin(t * (0.050 + 0.011 * fk) + fk * 1.7);
    rad *= 1.0 + 0.16 * sin(t * (0.043 + 0.007 * fk) + fk * 2.3);
    vec2 c = rad * vec2(cos(ang), sin(ang));
    if (k == 4) c = 0.08 * vec2(sin(t * 0.061), cos(t * 0.047));
    return c;
}

// Smoothed hyperbolic Green kernel around c. x = rho^2, rho = tanh(d/2) the pseudo-hyperbolic
// distance |u-c| / |1 - conj(c) u|. Outside the core (rho > rho0) K = log rho (the exact Green
// function of the hyperbolic Laplacian, up to 1/2pi); inside, a C2 polynomial in rho^2 with
// zero gradient at the centre, so the flow is smooth and bounded.
// g = Euclidean gradient of K in disk coordinates. F = flux fraction (1 outside the core).
float hp_kernel(vec2 u, vec2 c, float x0, out vec2 g, out float F, out vec2 nm) {
    vec2 n = u - c;
    vec2 m = vec2(1.0 - dot(c, u), c.y * u.x - c.x * u.y);       // 1 - conj(c) u
    float m2 = max(dot(m, m), 1e-8);
    float x = dot(n, n) / m2;
    vec2 P = vec2(n.x * m.x - n.y * m.y, n.x * m.y + n.y * m.x);  // n * m
    float FoverX;
    float K;
    if (x < x0) {
        float s = x / x0;
        F = s * (2.0 - s);
        FoverX = (2.0 - s) / x0;
        K = s - 0.25 * s * s + 0.5 * log(x0) - 0.75;
    } else {
        F = 1.0;
        FoverX = 1.0 / x;
        K = 0.5 * log(x);
    }
    g = (1.0 - dot(c, c)) * FoverX * P / (m2 * m2);
    nm = vec2(n.x * m.x + n.y * m.y, n.y * m.x - n.x * m.y);      // n * conj(m): arg = angle around c
    return K;
}

// Helmholtz flow: v = grad_H phi + J grad_H psi = lambda^-2 (grad_E phi + J grad_E psi).
// Returns the disk-coordinate velocity; phi = scalar potential.
vec2 hp_flow(vec2 u, float t, vec3 str, float x0, out float phi) {
    phi = 0.0;
    vec2 gphi = vec2(0.0);
    vec2 gpsi = vec2(0.0);
    for (int k = 0; k < 7; k++) {
        vec2 g;
        float F;
        vec2 nm;
        float K = hp_kernel(u, hp_center(k, t), x0, g, F, nm);
        if (k < 2) { phi += str.x * K; gphi += str.x * g; }
        else if (k < 4) { phi -= str.y * K; gphi -= str.y * g; }
        else { float sg = k == 4 ? 1.0 : -1.0; gpsi += sg * str.z * g; }
    }
    float l = 1.0 - dot(u, u);
    return (gphi + vec2(-gpsi.y, gpsi.x)) * (0.25 * l * l);
}


// Disk point at hyperbolic offset z (disk coords around 0) from c: Mobius (z + c) / (1 + conj(c) z)
vec2 hp_mobius(vec2 z, vec2 c) {
    vec2 num = z + c;
    vec2 den = vec2(1.0 + c.x * z.x + c.y * z.y, c.x * z.y - c.y * z.x);
    return vec2(num.x * den.x + num.y * den.y, num.y * den.x - num.x * den.y) / max(dot(den, den), 1e-8);
}

vec4 helmholtzParticles(sampler2D state, float time, float count, float flowSpeed, float sourceStrength, float sinkStrength, float vortexStrength, float core, float lifetime, float sphereSize, float arcHeight) {
    ivec2 px = ivec2(gl_FragCoord.xy);
    int i = px.x;
    int row = px.y;
    vec4 s0 = texelFetch(state, ivec2(i, 0), 0);
    vec4 s1 = texelFetch(state, ivec2(i, 1), 0);
    vec4 s2 = texelFetch(state, ivec2(i, 2), 0);
    vec3 str = vec3(sourceStrength, sinkStrength, vortexStrength);
    float x0 = max(core * core, 1e-4);

    vec2 u = s0.xy;
    float age = s0.z;
    float gen = s0.w;
    float life = s2.w;
    // First frame (zeroed buffer), clock reset or a broken state: reseed everything
    bool init = s1.w <= 0.0 || time < s1.w - 1.0 || !(dot(u, u) < 0.99) || !(life > 0.0);
    float dt = init ? 0.0 : clamp(time - s1.w, 0.0, 0.1);
    vec2 uPrev = u;
    bool respawn = init;

    if (!init) {
        // RK4 in disk coordinates (the field drifts slowly, so it is frozen during a step)
        float h = dt * flowSpeed;
        float ph;
        vec2 k1 = hp_flow(u, time, str, x0, ph);
        vec2 k2 = hp_flow(u + 0.5 * h * k1, time, str, x0, ph);
        vec2 k3 = hp_flow(u + 0.5 * h * k2, time, str, x0, ph);
        vec2 k4 = hp_flow(u + h * k3, time, str, x0, ph);
        u += h / 6.0 * (k1 + 2.0 * k2 + 2.0 * k3 + k4);
        age += dt;
        // Swallowed by a sink: finish the life (shrink while merging with the others)
        for (int k = 2; k < 4; k++) {
            vec2 c = hp_center(k, time);
            vec2 n = u - c;
            vec2 m = vec2(1.0 - dot(c, u), c.y * u.x - c.x * u.y);
            if (dot(n, n) / max(dot(m, m), 1e-8) < x0 * 0.3) age = max(age, life - 1.8);
        }
        if (age > life || !(dot(u, u) < 0.64)) respawn = true;
    }

    if (respawn) {
        gen = init ? floor(hp_hash3(uvec3(uint(i), 17u, 3u)).x * 1000.0) : gen + 1.0;
        vec3 r = hp_hash3(uvec3(uint(i), uint(gen), 7u));
        vec3 r2 = hp_hash3(uvec3(uint(i), uint(gen), 911u));
        life = max(lifetime, 1.0) * mix(0.6, 1.4, r.z);
        float a = 6.2831853 * r2.y;
        if (r.x < 0.85 && !init) {
            // Near a source, at hyperbolic distance 0.1..0.3
            vec2 c = hp_center(r.y < 0.5 ? 0 : 1, time);
            float d = mix(0.10, 0.30, r2.x);
            u = hp_mobius(tanh(0.5 * d) * vec2(cos(a), sin(a)), c);
        } else {
            // Anywhere within hyperbolic radius 1.2 (uniform in hyperbolic area)
            float rr = acosh(1.0 + (cosh(1.2) - 1.0) * r2.x);
            u = tanh(0.5 * rr) * vec2(cos(a), sin(a));
        }
        age = init ? life * 0.8 * r2.z : 0.0;
        uPrev = u;
    }

    float phi;
    vec2 vel = hp_flow(u, time, str, x0, phi) * flowSpeed;
    float l = max(1.0 - dot(u, u), 1e-4);
    float speed = length(vel) * 2.0 / l;                 // hyperbolic speed
    float phiN = tanh(0.8 * phi);
    float tt = 0.5 + 0.5 * phiN;                          // 0 at sources .. 1 at sinks
    float env = smoothstep(0.0, 0.8, age) * (1.0 - smoothstep(life - 1.5, life, age));
    if (float(i) >= count) env = 0.0;
    float rad = sphereSize * env * (0.8 + 0.4 * fract(gen * 0.618 + float(i) * 0.37));
    float hgt = sphereSize * 1.2 + arcHeight * 4.0 * tt * (1.0 - tt);
    vec4 q0 = vec4(2.0 * u.x, 0.0, 2.0 * u.y, 1.0 + dot(u, u)) / l;
    vec4 c = cosh(hgt) * q0 + vec4(0.0, sinh(hgt), 0.0, 0.0);

    if (row == 0) return vec4(u, age, gen);
    if (row == 1) return vec4(uPrev, dt, time);
    if (row == 2) return vec4(vel, phiN, life);
    if (row == 3) return c;
    return vec4(rad, tt, speed, env);
}

