vec4 helmholtzCanvas(sampler2D canvas, sampler2D particles, float time, float count, float flowSpeed, float sourceStrength, float sinkStrength, float vortexStrength, float core, float trailFade, float trailWidth) {
    vec2 res = vec2(textureSize(canvas, 0));
    vec2 uv01 = gl_FragCoord.xy / res;
    vec2 u = uv01 * 2.0 - 1.0;
    float r2 = dot(u, u);
    if (r2 > 0.995) return vec4(0.0, 0.5, 0.0, 1.0);
    vec3 str = vec3(sourceStrength, sinkStrength, vortexStrength);
    float x0 = max(core * core, 1e-4);
    float dt = texelFetch(particles, ivec2(0, 1), 0).z;

    // Dye: semi-Lagrangian advection + pulsing noise injection (van Wijk's IBFV)
    float phi;
    vec2 vel = hc_flow(u, time, str, x0, phi) * flowSpeed;
    vec2 back = u - vel * dt;
    vec4 adv = texture(canvas, back * 0.5 + 0.5);
    vec4 here = texelFetch(canvas, ivec2(gl_FragCoord.xy), 0);
    vec3 hn = hc_hash3(uvec3(uvec2(gl_FragCoord.xy * 0.5), 5u));
    float pulse = smoothstep(0.35, 0.5, fract(time * 0.45 + hn.x)) * (1.0 - smoothstep(0.75, 0.9, fract(time * 0.45 + hn.x)));
    float alpha = 1.0 - exp(-dt * 1.6);
    float dye = mix(adv.g, pulse, alpha);

    // Trails: stationary, fading; splat each particle's last step as a segment
    float tr = here.r * exp(-dt / max(trailFade, 0.05));
    float tint = here.b;
    float lam = 2.0 / (1.0 - r2);
    int n = int(count);
    for (int i = 0; i < 64; i++) {
        if (i >= n) break;
        vec4 a = texelFetch(particles, ivec2(i, 0), 0);
        vec2 d0 = u - a.xy;
        if (dot(d0, d0) > 0.0025) continue;
        vec4 b = texelFetch(particles, ivec2(i, 1), 0);
        vec4 e = texelFetch(particles, ivec2(i, 4), 0);
        vec2 ab = a.xy - b.xy;
        float hh = clamp(dot(u - b.xy, ab) / max(dot(ab, ab), 1e-12), 0.0, 1.0);
        float dH = length(u - b.xy - ab * hh) * lam;
        float w = trailWidth * (0.5 + 0.5 * e.w);
        float s = exp(-dH * dH / max(w * w, 1e-8)) * e.w;
        tint = mix(tint, e.y, s / max(tr + s, 1e-5));
        tr = max(tr, s);
    }
    return vec4(tr, dye, tint, 1.0);
}

