float hr_dot(vec4 a, vec4 b) {
    return dot(a.xyz, b.xyz) - a.w * b.w;
}

// Full field for the map: potential phi, total stream function Psi = sum(+-q theta) - psi
// (theta = angle around each source / sink = harmonic conjugate of log rho; the source flow is
// radial, so its streamlines are exactly the rays theta = const; strengths quantized to the line
// spacing S so the 2pi jumps at the angle branch cuts never show), psi, and the
// Euclidean disk gradients of phi and of the flow (vE = grad phi + J grad psi).
void hr_fieldMap(vec2 u, float t, vec3 str, float x0, float S, out float phi, out float Psi, out vec2 gphi, out vec2 vE, out float psi) {
    phi = 0.0;
    Psi = 0.0;
    psi = 0.0;
    gphi = vec2(0.0);
    vec2 gpsi = vec2(0.0);
    float qs = S * floor(str.x * 6.2831853 / S + 0.5) / 6.2831853;
    float qk = S * floor(str.y * 6.2831853 / S + 0.5) / 6.2831853;
    for (int k = 0; k < 7; k++) {
        vec2 g;
        float F;
        vec2 nm;
        float K = hr_kernel(u, hr_center(k, t), x0, g, F, nm);
        float th = atan(nm.y, nm.x);
        if (k < 2) { phi += str.x * K; gphi += str.x * g; Psi += qs * th; }
        else if (k < 4) { phi -= str.y * K; gphi -= str.y * g; Psi -= qk * th; }
        else { float sg = k == 4 ? 1.0 : -1.0; psi += sg * str.z * K; gpsi += sg * str.z * g; }
    }
    Psi -= psi;
    vE = gphi + vec2(-gpsi.y, gpsi.x);
}

// Orbiting camera: circle of hyperbolic radius ~1 around the origin, height ~0.5 above the plane
void hr_camera(float t, float speed, out vec4 p, out vec4 F, out vec4 R, out vec4 U) {
    float th = t * speed + 2.2;
    float Rr = 1.0 + 0.12 * sin(t * 0.031);
    float H = 0.5 + 0.06 * sin(t * 0.047 + 1.0);
    vec4 p0 = vec4(sinh(Rr) * cos(th), 0.0, sinh(Rr) * sin(th), cosh(Rr));
    vec4 T0 = vec4(-sin(th), 0.0, cos(th), 0.0);
    vec4 Rad = vec4(cosh(Rr) * cos(th), 0.0, cosh(Rr) * sin(th), sinh(Rr));
    p = cosh(H) * p0 + vec4(0.0, sinh(H), 0.0, 0.0);
    vec4 Up = sinh(H) * p0 + vec4(0.0, cosh(H), 0.0, 0.0);
    float yaw = 0.68 + 0.18 * sin(t * 0.039);
    float pitch = 0.68 + 0.06 * sin(t * 0.057 + 0.5);
    vec4 Hd = cos(yaw) * T0 - sin(yaw) * Rad;
    R = -cos(yaw) * Rad - sin(yaw) * T0;
    F = cos(pitch) * Hd - sin(pitch) * Up;
    U = sin(pitch) * Hd + cos(pitch) * Up;
}

// Change of disk coordinates for a tangent displacement D at a plane point q (y = 0)
vec2 hr_diskDiff(vec4 q, vec4 D) {
    float iw = 1.0 / (1.0 + q.w);
    return vec2(D.x - q.x * D.w * iw, D.z - q.z * D.w * iw) * iw;
}

// Anti-aliased isoline: x in line units, fw = change of x per pixel
float hr_iso(float x, float fw, float wpx) {
    float d = abs(fract(x + 0.5) - 0.5);
    float pxd = d / max(fw, 1e-6);
    return (1.0 - smoothstep(wpx * 0.5 - 0.5, wpx * 0.5 + 0.7, pxd)) * (1.0 - smoothstep(0.12, 0.35, fw));
}

vec3 hr_sphereColor(vec4 e, vec3 a, vec3 b) {
    vec3 c = mix(a, b, smoothstep(0.4, 0.9, e.y));
    float sp = clamp(e.z * 1.5, 0.0, 1.5);
    return c * (0.7 + 0.8 * sp) + vec3(0.12) * sp;
}

// Sky: the ideal boundary. q + V is the null vector of the ray's endpoint at infinity.
vec3 hr_sky(vec4 q, vec4 V, vec3 a, vec3 b) {
    vec4 e = q + V;
    vec3 xi = e.xyz / max(e.w, 1e-6);
    float y = xi.y;
    vec3 col = mix(vec3(0.02, 0.03, 0.06), vec3(0.002, 0.003, 0.009), smoothstep(0.0, 0.6, y));
    col += (a * 0.4 + b * 0.6 + vec3(0.2, 0.3, 0.4)) * 0.06 * exp(-abs(y) * 12.0);
    // faint nebula on the ideal sphere, tinted by the two palette colors
    float nb = sin(xi.x * 3.1 + sin(xi.z * 4.3 + xi.y * 2.0)) * sin(xi.z * 2.7 - xi.y * 3.3 + sin(xi.x * 5.1));
    float nb2 = sin(xi.x * 7.3 - xi.z * 6.1 + nb * 2.0) * 0.5 + 0.5;
    col += mix(a, b, 0.5 + 0.5 * nb) * 0.022 * smoothstep(0.0, 1.0, nb * 0.5 + 0.5) * nb2 * smoothstep(-0.05, 0.3, y) * (1.0 - smoothstep(0.4, 0.9, y));
    vec3 sp = xi * 150.0;
    vec3 h = hr_hash3(uvec3(ivec3(floor(sp)) + 4096));
    vec3 f = fract(sp) - 0.5 - (h - 0.5) * 0.6;
    col += vec3(0.65, 0.78, 1.0) * step(0.93, h.x) * exp(-dot(f, f) * 70.0) * (0.25 + 0.75 * h.y) * smoothstep(0.03, 0.25, y);
    return col;
}

// The field map on the plane at disk point u; dux / duy = disk-coordinate change per pixel
vec3 hr_map(vec2 u, vec2 dux, vec2 duy, float t, vec3 str, float x0, float S, sampler2D canvas, vec3 srcCol, vec3 snkCol, vec3 lineCol, float music, out float phiN) {
    float phi;
    float Psi;
    float psi;
    vec2 gphi;
    vec2 vE;
    hr_fieldMap(u, t, str, x0, S, phi, Psi, gphi, vE, psi);
    float l = max(1.0 - dot(u, u), 1e-5);
    float speed = length(vE) * 0.5 * l;
    phiN = tanh(0.8 * phi);
    float pc = tanh(0.45 * phi);
    float a = smoothstep(0.05, 0.95, -pc);
    float b = smoothstep(0.15, 1.0, pc);
    vec3 col = vec3(0.018, 0.075, 0.090) * (1.0 - smoothstep(0.0, 0.6, abs(pc)));
    col += vec3(0.007, 0.009, 0.020);
    col += srcCol * 0.42 * a * a + snkCol * 0.28 * b * b;

    // Canvas: advected dye (flow texture) and particle trails
    vec4 cv = texture(canvas, u * 0.5 + 0.5);
    float texel = max(length(dux), length(duy)) * 0.5 * float(textureSize(canvas, 0).x);
    float dyeVis = (1.0 - smoothstep(0.7, 3.0, texel)) * smoothstep(0.03, 0.15, speed);
    col *= 1.0 + (cv.g - 0.5) * 1.1 * dyeVis;

    // Equipotentials and streamlines with analytic screen-space derivatives
    vec2 gPsi = vec2(-vE.y, vE.x);
    float fwPsi = length(vec2(dot(gPsi, dux), dot(gPsi, duy))) / S;
    float fwPhi = length(vec2(dot(gphi, dux), dot(gphi, duy))) / S;
    // Music: a front of light rides the potential from the sources (phiN = -1) to the sinks (+1) over each beat
    float bph = u_beatPhase;
    float front = (phiN - mix(-0.95, 0.95, 1.0 - (1.0 - bph) * (1.0 - bph))) / 0.11;
    float wave = music * u_beatConfidence * smoothstep(0.25, 0.75, u_beatTrust) * exp(-front * front) * (1.0 - bph * bph) * smoothstep(0.0, 0.03, bph);
    col += lineCol * hr_iso(Psi / S, fwPsi, 1.5) * 0.7 * (1.0 + 2.2 * wave);
    col += mix(srcCol, snkCol, 0.5 + 0.5 * phiN) * hr_iso(phi / S, fwPhi, 1.1) * 0.35 * (1.0 + 1.5 * wave);
    col += mix(srcCol, snkCol, 0.5 + 0.5 * phiN) * 0.05 * wave;

    vec3 tc = mix(srcCol, snkCol, smoothstep(0.4, 0.9, cv.b));
    col += (tc * 1.4 + 0.15) * cv.r * (1.0 - smoothstep(1.5, 5.0, texel)) * 0.6;

    // Sources (bright), sinks (dark wells with a rim), vortices (soft cores)
    for (int k = 0; k < 7; k++) {
        vec2 c = hr_center(k, t);
        vec2 n = u - c;
        vec2 m = vec2(1.0 - dot(c, u), c.y * u.x - c.x * u.y);
        float rho = sqrt(dot(n, n) / max(dot(m, m), 1e-8));
        float d = 2.0 * atanh(min(rho, 0.9999));
        if (k < 2) {
            col += srcCol * (1.7 * exp(-d * d / 0.003) + 0.45 * exp(-d * d / 0.04)) * str.x;
            float ph = fract(t * 0.35 + float(k) * 0.5);
            float wv = (d - 0.05 - ph * 0.45) / 0.012;
            col += srcCol * 0.6 * exp(-wv * wv) * (1.0 - ph) * str.x;
        } else if (k < 4) {
            col *= mix(0.15, 1.0, smoothstep(0.02, 0.16, d));
            float rr = (d - 0.13) / 0.025;
            col += snkCol * 0.8 * exp(-rr * rr) * str.y;
            float ph = fract(t * 0.3 + float(k) * 0.37);
            float wv = (d - 0.14 - (1.0 - ph) * 0.4) / 0.01;
            col += snkCol * 0.3 * exp(-wv * wv) * ph * str.y;
        } else {
            col += lineCol * 0.25 * exp(-d * d / 0.01) * str.z;
        }
    }
    return col;
}

// What a reflected ray from q sees: the map (soft lines) or the sky
vec3 hr_env(vec4 q, vec4 Rf, float t, vec3 str, float x0, float S, sampler2D canvas, vec3 srcCol, vec3 snkCol, vec3 lineCol, float fog, float music) {
    if (Rf.y < -1e-5) {
        float tt = -q.y / Rf.y;
        if (tt < 0.9999) {
            float s = atanh(max(tt, 0.0));
            vec4 h = cosh(s) * q + sinh(s) * Rf;
            vec2 u = h.xz / (1.0 + h.w);
            float phiN;
            vec3 m = hr_map(u, vec2(0.004), vec2(0.004), t, str, x0, S, canvas, srcCol, snkCol, lineCol, music, phiN);
            return mix(hr_sky(q, Rf, srcCol, snkCol), m, exp(-s * fog));
        }
    }
    return hr_sky(q, Rf, srcCol, snkCol);
}

vec3 hyperbolicCurrents(vec2 uv, float time, sampler2D particles, sampler2D canvas, float count, float sourceStrength, float sinkStrength, float vortexStrength, float core, float smoothK, float lineCount, float glow, float fog, float camSpeed, vec3 sourceColor, vec3 sinkColor, vec3 lineColor, float music) {
    vec3 str = vec3(sourceStrength, sinkStrength, vortexStrength);
    float x0 = max(core * core, 1e-4);
    float qref = max(max(str.x, str.y), 0.05);
    float S = 6.2831853 * qref / max(lineCount, 1.0);
    float k = max(smoothK, 1e-4);
    float kP = k * 1.3;

    vec4 p;
    vec4 F;
    vec4 R;
    vec4 U;
    hr_camera(time, camSpeed, p, F, R, U);
    float foc = 1.7;
    float wl = sqrt(dot(uv, uv) + foc * foc);
    vec4 v = (uv.x * R + uv.y * U + foc * F) / wl;
    float pix = 2.0 / u_resolution.y;
    vec4 Ex = (R - v * (uv.x / wl)) * (pix / wl);
    vec4 Ey = (U - v * (uv.y / wl)) * (pix / wl);

    // Plane y = 0: <gamma(s), n> = cosh(s) p.y + sinh(s) v.y = 0
    float sP = 1e4;
    if (v.y < -1e-6) {
        float tt = -p.y / v.y;
        if (tt < 0.99999) sP = atanh(tt);
    }
    float sMax = min(sP, 8.0);
    float chM = cosh(sMax);
    float shM = sinh(sMax);

    // Particles: closest approach of the ray (halo) and candidates for sphere tracing
    int n = int(count);
    vec4 cc[12];
    vec4 ce[12];
    int nc = 0;
    float sIn = 1e4;
    float sOut = -1.0;
    vec3 halo = vec3(0.0);
    for (int i = 0; i < 64; i++) {
        if (i >= n) break;
        vec4 e = texelFetch(particles, ivec2(i, 4), 0);
        if (e.x < 1e-4) continue;
        vec4 c = texelFetch(particles, ivec2(i, 3), 0);
        float A = -hr_dot(p, c);
        float B = -hr_dot(v, c);
        float ts = -B / A;
        // cosh^2 of the closest distance over s in [0, sMax]
        float f = ts <= 0.0 ? A : (ts >= tanh(sMax) ? A * chM + B * shM : sqrt(max(A * A - B * B, 1.0)));
        float sh2 = max(f * f - 1.0, 0.0);
        float w = e.x * 2.0 + 0.01;
        float sc = clamp(atanh(clamp(ts, 0.0, 0.9999)), 0.0, sMax);
        float hl = 1.0 / (1.0 + sh2 / (w * w));
        halo += hr_sphereColor(e, sourceColor, sinkColor) * e.w * hl * hl * exp(-sc * fog);
        float Rr = e.x + 1.25 * kP + 0.005;
        float shR = sinh(Rr);
        if (sh2 < shR * shR && nc < 12) {
            float C = cosh(Rr);
            float disc = C * C - (A * A - B * B);
            if (disc > 0.0) {
                float sq = sqrt(disc);
                float s1 = log(max((C - sq) / (A + B), 1e-6));
                float s2 = log(max((C + sq) / (A + B), 1e-6));
                if (s2 > 0.0 && s1 < sMax) {
                    cc[nc] = c;
                    ce[nc] = e;
                    nc++;
                    sIn = min(sIn, max(s1, 0.0));
                    sOut = max(sOut, min(s2, sMax + 0.02));
                }
            }
        }
    }

    // Sphere tracing along the geodesic gamma(s) = cosh(s) p + sinh(s) v, smin(spheres) smin plane
    float sHit = -1.0;
    if (nc > 0) {
        float s = sIn;
        for (int it = 0; it < 80; it++) {
            vec4 q = cosh(s) * p + sinh(s) * v;
            float dS = 1e4;
            for (int j = 0; j < 12; j++) {
                if (j >= nc) break;
                float dj = acosh(max(-hr_dot(q, cc[j]), 1.0)) - ce[j].x;
                float h = clamp(0.5 + 0.5 * (dS - dj) / k, 0.0, 1.0);
                dS = mix(dS, dj, h) - k * h * (1.0 - h);
            }
            float dPl = asinh(q.y);
            float h = clamp(0.5 + 0.5 * (dPl - dS) / kP, 0.0, 1.0);
            float d = mix(dPl, dS, h) - kP * h * (1.0 - h);
            if (d < 0.0003 * (1.0 + 2.0 * s)) { sHit = s; break; }
            s += d;
            if (s > sOut) break;
        }
    }

    vec3 col;
    float sEnd = 8.0;
    if (sHit >= 0.0 || sP < 1e4) {
        bool marched = sHit >= 0.0;
        float s = marched ? sHit : sP;
        sEnd = s;
        vec4 q = cosh(s) * p + sinh(s) * v;
        vec4 V = sinh(s) * p + cosh(s) * v;
        float wS = 0.0;
        vec4 N = vec4(0.0, 1.0, 0.0, 0.0);
        vec4 eS = vec4(0.0);
        if (marched) {
            // Normal = tangent gradient through the same smin chain (exact for quadratic smin)
            float dS = 1e4;
            vec4 gS = vec4(0.0);
            for (int j = 0; j < 12; j++) {
                if (j >= nc) break;
                float ch = max(-hr_dot(q, cc[j]), 1.0);
                float dj = acosh(ch) - ce[j].x;
                vec4 gj = -(cc[j] - ch * q) / max(sqrt(ch * ch - 1.0), 1e-6);
                float h = clamp(0.5 + 0.5 * (dS - dj) / k, 0.0, 1.0);
                dS = mix(dS, dj, h) - k * h * (1.0 - h);
                gS = mix(gS, gj, h);
                eS = mix(eS, ce[j], h);
            }
            float dPl = asinh(q.y);
            vec4 gP = (vec4(0.0, 1.0, 0.0, 0.0) + q.y * q) / cosh(dPl);
            wS = clamp(0.5 + 0.5 * (dPl - dS) / kP, 0.0, 1.0);
            vec4 g = mix(gP, gS, wS);
            g += hr_dot(g, q) * q;
            N = g / sqrt(max(hr_dot(g, g), 1e-12));
        }

        vec3 planeCol = vec3(0.0);
        vec3 sphCol = vec3(0.0);
        if (wS < 0.999) {
            vec4 q0 = vec4(q.x, 0.0, q.z, q.w) / sqrt(max(q.w * q.w - q.x * q.x - q.z * q.z, 1e-6));
            vec2 u = q0.xz / (1.0 + q0.w);
            float sv = sinh(s);
            float vy = min(V.y, -1e-4);
            vec2 dux = hr_diskDiff(q0, sv * (Ex - (Ex.y / vy) * V));
            vec2 duy = hr_diskDiff(q0, sv * (Ey - (Ey.y / vy) * V));
            float phiN;
            vec3 base = hr_map(u, dux, duy, time, str, x0, S, canvas, sourceColor, sinkColor, lineColor, music, phiN);
            // Sphere light on the floor (1/sinh^2 falloff, cosine = sinh(h)/sinh(d)) and the glossy
            // mirror image of the spheres (closest approach of the reflected geodesic)
            vec4 Vr = vec4(V.x, -V.y, V.z, V.w);
            vec3 light = vec3(0.0);
            vec3 refl = vec3(0.0);
            for (int i = 0; i < 64; i++) {
                if (i >= n) break;
                vec4 e = texelFetch(particles, ivec2(i, 4), 0);
                if (e.x < 1e-4) continue;
                vec4 c = texelFetch(particles, ivec2(i, 3), 0);
                vec3 scol = hr_sphereColor(e, sourceColor, sinkColor) * e.w;
                float A = max(-hr_dot(q0, c), 1.0);
                float inv = inversesqrt(A * A - 1.0 + 0.003);
                light += scol * (e.x * e.x * c.y) * inv * inv * inv;
                float B = -hr_dot(Vr, c);
                float f2 = B < 0.0 ? A * A - B * B : A * A;
                float w = e.x * 2.0 + 0.01;
                float hl = 1.0 / (1.0 + max(f2 - 1.0, 0.0) / (w * w));
                refl += scol * hl * hl;
            }
            float fr = 0.05 + 0.6 * pow(1.0 - abs(V.y), 5.0);
            planeCol = base + light * glow * 0.35 + refl * fr * glow * 1.2;
        }
        if (wS > 0.001) {
            vec3 scol = hr_sphereColor(eS, sourceColor, sinkColor);
            float NdV = clamp(-hr_dot(N, V), 0.0, 1.0);
            vec4 Rf = V - 2.0 * hr_dot(V, N) * N;
            vec3 env = hr_env(q, Rf, time, str, x0, S, canvas, sourceColor, sinkColor, lineColor, fog, music);
            float fr = 0.04 + 0.96 * pow(1.0 - NdV, 5.0);
            // light from straight above: unit normal of the equidistant surface through q
            vec4 L = (vec4(0.0, 1.0, 0.0, 0.0) + q.y * q) / sqrt(1.0 + q.y * q.y);
            vec4 Hh = L - V;
            Hh /= sqrt(max(hr_dot(Hh, Hh), 1e-8));
            float spec = pow(max(hr_dot(N, Hh), 0.0), 80.0);
            sphCol = scol * (0.07 + 1.05 * pow(NdV, 3.0)) * glow + env * (0.2 + 0.9 * fr) + scol * pow(1.0 - NdV, 3.0) * 0.6 + vec3(1.0, 0.95, 0.9) * spec * 0.9;
        }
        col = mix(planeCol, sphCol, wS);
        vec3 fogCol = hr_sky(p, v, sourceColor, sinkColor) * 0.6 + vec3(0.016, 0.024, 0.05);
        col = mix(fogCol, col, exp(-s * fog));
    } else {
        col = hr_sky(p, v, sourceColor, sinkColor);
    }
    col += halo * glow * 0.25;
    return col;
}
